-- ============================================
-- LUMA — Thème 13 : LONG 3/3 x4 — Présenter son propre projet devant un public
-- ============================================


update scenarios set content = '{"characters": {"host": "l''animateur", "skeptic": "le sceptique", "audience_member1": "public 1", "audience_member2": "public 2"}, "start_node": "n1", "nodes": {"n1": {"speaker": "host", "text": "And now, please welcome our next presenter to share their project with us!", "text_fr": "Et maintenant, veuillez accueillir notre prochain présentateur pour partager son projet avec nous !", "choices": [{"text": "(Take a deep breath and walk confidently to the stage.)", "text_fr": "(Prends une grande respiration et marche vers la scène avec assurance.)", "next": "n2"}, {"text": "(Feel a wave of nerves, but proceed to the stage anyway.)", "text_fr": "(Ressens une vague de nervosité, mais avance quand même vers la scène.)", "next": "n2b"}]}, "n2": {"speaker": "you_thought", "text": "(Standing at the podium, you scan the attentive faces in the audience.)", "text_fr": "(Debout au podium, vous scannez les visages attentifs dans le public.)", "choices": [{"text": "Thank you all for being here. Let me tell you about a problem worth solving.", "text_fr": "Merci à tous d''être ici. Laissez-moi vous parler d''un problème qui vaut la peine d''être résolu.", "next": "n3"}]}, "n2b": {"speaker": "you_thought", "text": "(Despite the nerves, you find your voice steadying as you begin.)", "text_fr": "(Malgré la nervosité, vous trouvez votre voix se stabiliser en commençant.)", "choices": [{"text": "Good afternoon everyone. I''m excited to share something I''ve been building.", "text_fr": "Bon après-midi à tous. Je suis ravi de partager quelque chose que je construis.", "next": "n3"}]}, "n3": {"speaker": "you_thought", "text": "(You walk the audience through the core problem and your unique solution.)", "text_fr": "(Vous guidez le public à travers le problème central et votre solution unique.)", "choices": [{"text": "Continue with confidence, highlighting the key benefits of your approach.", "text_fr": "Continue avec assurance, en soulignant les avantages clés de ton approche.", "next": "n4"}]}, "n4": {"speaker": "audience_member1", "text": "(Nodding along, visibly engaged with the presentation.)", "text_fr": "(Hoche la tête, visiblement engagé avec la présentation.)", "choices": [{"text": "(Present your early results and traction, building credibility.)", "text_fr": "(Présente tes premiers résultats et ta traction, en construisant de la crédibilité.)", "next": "n5"}]}, "n5": {"speaker": "you_thought", "text": "(The room seems genuinely engaged, several people taking notes as you speak.)", "text_fr": "(La salle semble vraiment engagée, plusieurs personnes prenant des notes pendant que vous parlez.)", "choices": [{"text": "(Wrap up your presentation and open the floor for questions.)", "text_fr": "(Termine ta présentation et ouvre la parole pour les questions.)", "next": "n6"}]}, "n6": {"speaker": "host", "text": "Thank you for that presentation! Let''s open it up for questions from the audience.", "text_fr": "Merci pour cette présentation ! Ouvrons ça aux questions du public.", "choices": [{"text": "(Wait nervously for the first question to come.)", "text_fr": "(Attends nerveusement que la première question arrive.)", "next": "n7"}]}, "n7": {"speaker": "skeptic", "text": "This sounds interesting, but honestly, how is this different from what''s already out there?", "text_fr": "Ça semble intéressant, mais honnêtement, en quoi c''est différent de ce qui existe déjà ?", "choices": [{"text": "Great question. Unlike existing solutions, we focus specifically on this underserved niche.", "text_fr": "Excellente question. Contrairement aux solutions existantes, on se concentre spécifiquement sur cette niche sous-desservie.", "next": "n8"}, {"text": "(Feel a moment of doubt, but answer honestly about the key differentiators.)", "text_fr": "(Ressens un moment de doute, mais réponds honnêtement sur les différenciateurs clés.)", "next": "n8"}]}, "n8": {"speaker": "skeptic", "text": "(Considers) That''s actually a fair point. I hadn''t thought about it from that angle.", "text_fr": "(Réfléchit) C''est en fait un point valable. J''y avais pas pensé sous cet angle.", "choices": [{"text": "I appreciate you pushing on that — it''s exactly the kind of question that sharpens our thinking.", "text_fr": "J''apprécie que vous insistiez là-dessus — c''est exactement le genre de question qui affine notre réflexion.", "next": "n9"}]}, "n9": {"speaker": "audience_member2", "text": "What are your biggest challenges moving forward with this project?", "text_fr": "Quels sont vos plus grands défis en avançant avec ce projet ?", "choices": [{"text": "Honestly, scaling while maintaining the quality that makes this special.", "text_fr": "Honnêtement, mettre à l''échelle tout en maintenant la qualité qui rend ça spécial.", "next": "n10"}]}, "n10": {"speaker": "host", "text": "Great insights today. Any final thoughts before we wrap up this session?", "text_fr": "D''excellentes idées aujourd''hui. Des dernières pensées avant qu''on termine cette session ?", "choices": [{"text": "Just that I''m genuinely grateful for this thoughtful engagement from all of you today.", "text_fr": "Juste que je suis vraiment reconnaissant pour cet engagement réfléchi de votre part aujourd''hui.", "next": "n11"}]}, "n11": {"speaker": "skeptic", "text": "(Approaches after the session) I wanted to say — that was a really solid pitch. Good work.", "text_fr": "(S''approche après la session) Je voulais dire — c''était un pitch vraiment solide. Bon travail.", "choices": [{"text": "That means a lot, especially coming from someone who challenged me. Thank you.", "text_fr": "Ça compte beaucoup, surtout venant de quelqu''un qui m''a challengé. Merci.", "next": "end_pitched"}]}, "end_pitched": {"speaker": "skeptic", "text": "Challenges make ideas stronger. I look forward to seeing where this goes.", "text_fr": "Les défis renforcent les idées. J''ai hâte de voir où ça mène.", "end": true, "ending_label": "Projet présenté avec succès, objection surmontée 🎤💡"}}}'::jsonb, is_playable = true
where title = 'Présenter son propre projet devant un public'
  and theme_id = (select id from scenario_themes where position = 13 and language_id = (select id from languages where code = 'en'));
